"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[91614],{6809:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"LeviathanAnimConfig","desc":"Moves for LeviathanAnimator (the Leviathan boss mesh is code-animated: its\\nspine bones follow a path, the head, jaw and wing bones ride on top). Edit\\nmotion here.\\n\\nSpace: every Vector3 is in train space. Origin = train centre, +X = train rear\\n(the train heads -X), +Y = up, +Z = the train\'s left, -Z = its right.\\n\\nEach move:\\n- `Path`: head path control points (Catmull-Rom). The body trails behind the\\n  head along the same path; before point 1 it extends straight back.\\n- `Keys`: `{ time, point }` where the head is on the path. `point` is a\\n  control point index, fractions allowed (2.5 = halfway from 2 to 3). Smooth\\n  monotone interpolation, so two equal points hold the head still.\\n- `Wave`: swim undulation, studs (`Side`, `Up`), `Length` (studs per wave),\\n  `Speed` (waves per second). Grows from 0 at the head to full at the tail.\\n- `Flap`: wing beat, degrees and seconds per beat.\\n- `Jaw`: `{ time, degrees open }`, linear.\\n- `Aim` (optional): `{ time, 0..1 }` how much the head turns to the laser target.\\n- `Laser` (optional): `Charge`/`Fire` time windows. The target sweeps from\\n  `From` to `To` along the train: fractions of the train length (0.5 = rear\\n  end, -0.5 = front end), at height `Y` and side offset `Z`.\\n- `Events` (optional): `{ time, name }` sent to the animator\'s OnEvent.\\n- `FromCurrent` (optional): start from the current pose instead of `Path[1]`,\\n  with optional `Lead` points first (see `Slam`).","source":{"line":31,"path":"src/ReplicatedStorage/SharedModules/Configs/LeviathanAnimConfig.luau"}}')}}]);